from itertools import combinations

def triples_sum_to_zero(l: list):
    """
    triples_sum_to_zero takes a list of integers as input.
    It returns True if there exist three distinct numbers in the list whose sum is zero, and False if no such combination exists.

    Ensure the function accurately handles both positive and negative integers.
    """
    if len(l) < 3:
        return False

    for comb in combinations(l, 3):
        if sum(comb) == 0:
            return True

    return False

